INSERT INTO public.faq_items (id, sort_order, is_active, created_at, updated_at, question, answer) VALUES ('ddac4243-8829-4b37-a624-6977c513ca33', 2, true, '2026-10-16 11:45:24.60231+02', '2026-10-16 11:45:24.60231+02', '{"en": "How do I get to the venue?", "es": "", "pt": ""}', '{"en": "La Garriga de Castelladral is about 1.5 hours from Barcelona by car. We''re also arranging organised transport from Barcelona — details to follow. Let us know in your RSVP if you''d like a seat on the bus.", "es": "", "pt": ""}');
INSERT INTO public.faq_items (id, sort_order, is_active, created_at, updated_at, question, answer) VALUES ('9a204beb-44ea-4337-8034-41f0e5f489c6', 3, true, '2026-10-16 11:45:24.60231+02', '2026-10-16 11:45:24.60231+02', '{"en": "Is there parking at the venue?", "es": "", "pt": ""}', '{"en": "Yes, there is parking available at the venue. More details to follow closer to the date.", "es": "", "pt": ""}');
INSERT INTO public.faq_items (id, sort_order, is_active, created_at, updated_at, question, answer) VALUES ('9a00e130-c89a-4dcc-b5b6-058d8a8a0073', 4, true, '2026-10-16 11:45:24.60231+02', '2026-10-16 11:45:24.60231+02', '{"en": "Can I bring children?", "es": "", "pt": ""}', '{"en": "We love your little ones, but this is an adults-only celebration. We hope you can find childcare and join us for the day — it''ll be worth it!", "es": "", "pt": ""}');
INSERT INTO public.faq_items (id, sort_order, is_active, created_at, updated_at, question, answer) VALUES ('f1633bc9-87c7-4b35-abd3-c5e4ecc6d15d', 5, true, '2026-10-16 11:45:24.60231+02', '2026-10-16 11:45:24.60231+02', '{"en": "What time does the day start and end?", "es": "", "pt": ""}', '{"en": "The ceremony starts in the afternoon. The full schedule is on this page. The evening will go on late, so pace yourselves.", "es": "", "pt": ""}');
INSERT INTO public.faq_items (id, sort_order, is_active, created_at, updated_at, question, answer) VALUES ('f129cb8e-776b-480b-9ebf-2e806133d866', 6, true, '2026-10-16 11:45:24.60231+02', '2026-10-16 11:45:24.60231+02', '{"en": "Can I take photos during the ceremony?", "es": "", "pt": ""}', '{"en": "We''d love for you to be present in the moment during the ceremony itself — we have a photographer. Feel free to take as many photos as you like during the rest of the day.", "es": "", "pt": ""}');
INSERT INTO public.faq_items (id, sort_order, is_active, created_at, updated_at, question, answer) VALUES ('ae73a310-bb37-4de3-b429-7c7070613acf', 7, true, '2026-10-16 11:45:24.60231+02', '2026-10-16 11:45:24.60231+02', '{"en": "Will there be vegetarian and vegan options?", "es": "", "pt": ""}', '{"en": "Yes — please let us know your dietary requirements in the RSVP form and we''ll make sure you''re well looked after.", "es": "", "pt": ""}');
INSERT INTO public.faq_items (id, sort_order, is_active, created_at, updated_at, question, answer) VALUES ('bed9d5de-f98f-476c-8da6-f4b4fd03d83a', 8, true, '2026-10-16 11:45:24.60231+02', '2026-10-16 11:45:24.60231+02', '{"en": "What''s the weather like in October?", "es": "", "pt": ""}', '{"en": "October in Catalonia is generally mild and sunny — expect highs of around 18–22°C during the day, cooler in the evenings. We recommend bringing a light jacket.", "es": "", "pt": ""}');
